import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    """
    Downloads a zip file from a specified URL and extracts it to a local directory.

    Args:
        url (str): The URL of the zip file to download.
        filename (str): The name to save the downloaded zip file as.

    Returns:
        tuple: A tuple containing a status message (str) and a list of filenames (list) 
               extracted from the zip file. If an error occurs, the message contains 
               "Error" and the list is empty.
    """
    # Ensure the directories exist
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)

    zip_path = DOWNLOAD_DIR / filename

    # 1. Download the file
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.exceptions.RequestException as e:
        return (f"Error: Network-related exception occurred during download: {e}", [])
    except Exception as e:
        return (f"Error: An unexpected error occurred during file writing: {e}", [])

    # 2. Extract the file
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            # Get the list of files before extracting to return them
            extracted_filenames = zip_ref.namelist()
            zip_ref.extractall(ZIP_DIR)

        return ("Success: File downloaded and extracted.", extracted_filenames)
    except zipfile.BadZipFile as e:
        return (f"Error: File-related exception - The downloaded file is not a valid zip: {e}", [])
    except Exception as e:
        return (f"Error: File-related exception occurred during extraction: {e}", [])
